DECLARE
    v_profile_customer_id UUID;
    v_loyalty_points_id UUID;
    v_old_tier_name TEXT;
    v_new_tier_id UUID;
    v_admin_id UUID;
    v_bronze_tier_id UUID;
BEGIN
    v_admin_id := auth.uid();
    IF v_admin_id IS NULL THEN
        RAISE EXCEPTION 'not_authenticated';
    END IF;

    IF NOT public.is_employee(v_admin_id) THEN
        RAISE EXCEPTION 'permission_denied: only employees can adjust tier';
    END IF;

    SELECT pc.id INTO v_profile_customer_id
    FROM public.profile_customers pc
    WHERE pc.user_id = p_user_id
    LIMIT 1;

    IF v_profile_customer_id IS NULL THEN
        RAISE EXCEPTION 'Customer not found';
    END IF;

    SELECT lp.id, lt.name
    INTO v_loyalty_points_id, v_old_tier_name
    FROM public.loyalty_points lp
    LEFT JOIN public.loyalty_tiers lt ON lt.id = lp.loyalty_tier_id
    WHERE lp.profile_customer_id = v_profile_customer_id
    LIMIT 1;

    IF v_loyalty_points_id IS NULL THEN
        SELECT id INTO v_bronze_tier_id
        FROM public.loyalty_tiers
        WHERE LOWER(TRIM(name)) = 'bronze' AND is_active = true
        LIMIT 1;

        IF v_bronze_tier_id IS NULL THEN
            RAISE EXCEPTION 'Bronze tier not found in loyalty_tiers';
        END IF;

        INSERT INTO public.loyalty_points (
            profile_customer_id, loyalty_tier_id, point_balance, lifetime_points
        ) VALUES (
            v_profile_customer_id, v_bronze_tier_id, 0, 0
        )
        RETURNING id INTO v_loyalty_points_id;

        UPDATE public.profile_customers
        SET loyalty_point_id = v_loyalty_points_id, updated_at = now()
        WHERE id = v_profile_customer_id;

        v_old_tier_name := 'Bronze';
    END IF;

    v_old_tier_name := COALESCE(NULLIF(TRIM(v_old_tier_name), ''), 'Bronze');

    -- Case-insensitive tier name lookup
    SELECT id INTO v_new_tier_id
    FROM public.loyalty_tiers
    WHERE LOWER(TRIM(name)) = LOWER(TRIM(p_new_tier_name))
      AND is_active = true
    LIMIT 1;

    IF v_new_tier_id IS NULL THEN
        RAISE EXCEPTION 'New tier not found: %', p_new_tier_name;
    END IF;

    IF (SELECT loyalty_tier_id FROM public.loyalty_points WHERE id = v_loyalty_points_id) IS NOT DISTINCT FROM v_new_tier_id THEN
        RAISE EXCEPTION 'tier_unchanged: select a different tier';
    END IF;

    UPDATE public.loyalty_points
    SET loyalty_tier_id = v_new_tier_id,
        _override_changer_id = v_admin_id,
        manual_override_at = now()
    WHERE id = v_loyalty_points_id;

    UPDATE public.loyalty_points
    SET _override_changer_id = NULL
    WHERE id = v_loyalty_points_id;

    INSERT INTO public.loyalty_tier_history (
        profile_customer_id,
        old_tier,
        new_tier,
        change_type,
        change_reason,
        changer_id,
        changed_at
    ) VALUES (
        v_profile_customer_id,
        v_old_tier_name,
        (SELECT name FROM public.loyalty_tiers WHERE id = v_new_tier_id),
        'manual',
        COALESCE(NULLIF(TRIM(p_reason), ''), 'Manual override by support'),
        v_admin_id,
        NOW()
    );
END;

DECLARE
  v_discount record;
  v_coupon   record;
  v_user_id  uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN json_build_object('error', 'not_authenticated');
  END IF;

  -- Lock the coupon row FOR UPDATE to prevent race conditions (double-spend)
  SELECT cc.* INTO v_coupon
  FROM public.customer_coupons cc
  JOIN public.discounts d ON d.id = cc.discount_id
  WHERE d.code = upper(p_code)
    AND cc.customer_id = v_user_id
  FOR UPDATE;  -- Serialize concurrent requests for the same coupon

  IF NOT FOUND THEN
    -- Distinguish between "code not in system" vs "not collected by this user"
    -- by checking if the discount exists at all
    PERFORM 1 FROM public.discounts WHERE code = upper(p_code) AND is_active = true;
    IF FOUND THEN
      RETURN json_build_object('error', 'not_collected');
    ELSE
      RETURN json_build_object('error', 'invalid_code');
    END IF;
  END IF;

  -- Check already used (single-use per customer enforced here)
  IF v_coupon.used_at IS NOT NULL THEN
    RETURN json_build_object('error', 'already_used');
  END IF;

  -- Fetch discount details (SECURITY DEFINER bypasses RLS)
  SELECT * INTO v_discount FROM public.discounts WHERE id = v_coupon.discount_id;

  -- Check discount still active
  IF NOT v_discount.is_active THEN
    RETURN json_build_object('error', 'invalid_code');
  END IF;

  -- Check expiry
  IF v_discount.end_date IS NOT NULL AND v_discount.end_date < now() THEN
    RETURN json_build_object('error', 'expired');
  END IF;

  -- Check global usage limit
  IF v_discount.usage_limit IS NOT NULL AND v_discount.usage_count >= v_discount.usage_limit THEN
    RETURN json_build_object('error', 'exhausted');
  END IF;

  -- ✅ All checks passed. Atomically mark as used.
  UPDATE public.customer_coupons
  SET used_at = now()
  WHERE id = v_coupon.id;

  -- Increment global usage counter
  UPDATE public.discounts
  SET usage_count = usage_count + 1,
      updated_at  = now()
  WHERE id = v_discount.id;

  RETURN json_build_object(
    'id',                  v_discount.id,
    'code',                v_discount.code,
    'discount_type',       v_discount.discount_type,
    'discount_value',      v_discount.discount_value,
    'min_order_value',     COALESCE(v_discount.min_order_value, 0),
    'max_discount_amount', v_discount.max_discount_amount
  );
END;

DECLARE
    v_dev_role_id UUID;
BEGIN
    -- Check if approval_status changed to 'approved' AND role is not already set
    IF NEW.approval_status = 'approved' AND (OLD.approval_status IS NULL OR OLD.approval_status != 'approved') THEN
        -- Only assign default dev role if NO role is currently assigned
        IF NEW.role_employees_id IS NULL THEN
            -- Get the Dev role ID (case-insensitive, fallback to admin for backward compat)
            SELECT id INTO v_dev_role_id
            FROM public.role_employees
            WHERE LOWER(role_name) IN ('dev', 'admin')
            ORDER BY CASE WHEN LOWER(role_name) = 'dev' THEN 0 ELSE 1 END
            LIMIT 1;

            -- If dev role exists, assign it
            IF v_dev_role_id IS NOT NULL THEN
                NEW.role_employees_id := v_dev_role_id;
                RAISE NOTICE 'Dev role (%) assigned to employee: %', v_dev_role_id, NEW.email;
            ELSE
                RAISE WARNING 'Dev role not found in role_employees table';
            END IF;
        END IF;

        -- Ensure status is active only if user is already linked (signed up)
        IF NEW.user_id IS NOT NULL THEN
            NEW.status := 'active';
        ELSE
            NEW.status := 'inactive';
        END IF;
    END IF;

    RETURN NEW;
END;

DECLARE
    v_new_tier_id UUID;
BEGIN
    -- Only evaluate when lifetime points increase
    IF NEW.lifetime_points IS NOT DISTINCT FROM OLD.lifetime_points THEN
        RETURN NEW;
    END IF;

    -- Find the highest tier the user now qualifies for based on LIFETIME points.
    SELECT id
    INTO   v_new_tier_id
    FROM   public.loyalty_tiers
    WHERE  is_active = true
      AND  COALESCE(min_points, 0) <= NEW.lifetime_points
    ORDER  BY priority_level DESC
    LIMIT  1;

    -- Touch loyalty_tier_id if we resolved a tier AND it's different
    IF v_new_tier_id IS NOT NULL THEN
        NEW.loyalty_tier_id := v_new_tier_id;
    END IF;

    RETURN NEW;
END;

BEGIN
    -- Only try to link if user_id is not already provided
    IF NEW.user_id IS NULL THEN
        SELECT id INTO NEW.user_id
        FROM auth.users
        WHERE email = NEW.email
        LIMIT 1;

        IF NEW.user_id IS NOT NULL THEN
            RAISE NOTICE 'Auto-linked existing auth user % to new employee record for %', NEW.user_id, NEW.email;
        END IF;
    END IF;
    RETURN NEW;
END;

DECLARE
    v_user_id         UUID;
    v_mission_label   TEXT;
    v_points_awarded  INTEGER;
    v_is_one_time     BOOLEAN;
    v_resolved_code   TEXT;  -- canonical action_code for idempotency check
    v_lp_id           UUID;
    v_current_balance INTEGER;
    v_new_balance     INTEGER;
    v_pc_id           UUID;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'not_authenticated';
    END IF;

    -- Map legacy frontend codes to loyalty_activity_codes.action_code
    v_resolved_code := CASE p_action_type
        WHEN 'create_campaign' THEN 'first_campaign'
        WHEN 'connect_api'     THEN 'connect_ad_api'
        WHEN 'upgrade_plan'   THEN 'pro_upgrade'
        ELSE p_action_type
    END;

    -- 1. Look up in loyalty_activity_codes FIRST (canonical admin-managed)
    SELECT name, reward_points, true
    INTO v_mission_label, v_points_awarded, v_is_one_time
    FROM public.loyalty_activity_codes
    WHERE (action_code = v_resolved_code OR action_code = p_action_type)
      AND is_active = true
    LIMIT 1;

    -- 2. Fallback to loyalty_missions (legacy)
    IF v_mission_label IS NULL THEN
        SELECT label, points_awarded, COALESCE(is_one_time, true)
        INTO v_mission_label, v_points_awarded, v_is_one_time
        FROM public.loyalty_missions
        WHERE action_type = p_action_type AND is_active = true
        LIMIT 1;
        v_resolved_code := p_action_type;
    END IF;

    IF v_mission_label IS NULL THEN
        RAISE EXCEPTION 'mission_not_found: %', p_action_type;
    END IF;

    -- 3. Idempotency: check both resolved_code and original (for legacy completions)
    IF v_is_one_time THEN
        IF EXISTS (
            SELECT 1 FROM public.loyalty_mission_completions
            WHERE user_id = v_user_id
              AND (action_type = v_resolved_code OR action_type = p_action_type)
        ) THEN
            RETURN jsonb_build_object('success', false, 'reason', 'already_claimed');
        END IF;
    END IF;

    -- 4. Record completion (use resolved_code for consistency with loyalty_activity_codes)
    INSERT INTO public.loyalty_mission_completions (user_id, action_type)
    VALUES (v_user_id, v_resolved_code);

    -- 5. Get or create loyalty_points
    SELECT lp.id, COALESCE(lp.point_balance, 0)
    INTO v_lp_id, v_current_balance
    FROM public.profile_customers pc
    JOIN public.loyalty_points lp ON lp.profile_customer_id = pc.id
    WHERE pc.user_id = v_user_id
    FOR UPDATE OF lp;

    IF v_lp_id IS NULL THEN
        SELECT id INTO v_pc_id FROM public.profile_customers WHERE user_id = v_user_id;
        IF v_pc_id IS NULL THEN
            RAISE EXCEPTION 'profile_customers_not_found for user %', v_user_id;
        END IF;
        INSERT INTO public.loyalty_points (
            profile_customer_id, point_balance, lifetime_points, last_activity_at
        )
        VALUES (v_pc_id, 0, 0, now())
        RETURNING id INTO v_lp_id;
        v_current_balance := 0;
    END IF;

    v_new_balance := v_current_balance + COALESCE(v_points_awarded, 0);

    -- 6. Update BOTH point_balance and lifetime_points (lifetime_points triggers tier upgrade)
    UPDATE public.loyalty_points
    SET point_balance    = v_new_balance,
        lifetime_points = COALESCE(lifetime_points, 0) + COALESCE(v_points_awarded, 0),
        last_activity_at = now(),
        updated_at       = now()
    WHERE id = v_lp_id;

    -- 7. Log transaction
    INSERT INTO public.points_transactions (
        user_id, loyalty_points_id, transaction_type, points_amount, balance_after, description
    ) VALUES (
        v_user_id, v_lp_id, 'earn', COALESCE(v_points_awarded, 0), v_new_balance,
        'Mission: ' || v_mission_label
    );

    RETURN jsonb_build_object(
        'success', true,
        'points_awarded', COALESCE(v_points_awarded, 0),
        'new_balance', v_new_balance
    );
END;

DECLARE
    mem_usage_pct NUMERIC;
    disk_usage_pct NUMERIC;
BEGIN
    -- Calculate memory usage percentage
    IF NEW.total_memory > 0 THEN
        mem_usage_pct := (NEW.used_memory::numeric / NEW.total_memory::numeric) * 100;
    ELSE
        mem_usage_pct := 0;
    END IF;

    -- Calculate disk usage percentage
    IF NEW.disk_total > 0 THEN
        disk_usage_pct := (NEW.disk_used::numeric / NEW.disk_total::numeric) * 100;
    ELSE
        disk_usage_pct := 0;
    END IF;

    -- Determine status based on thresholds
    IF COALESCE(NEW.cpu_usage_percent, 0) > 90 OR disk_usage_pct > 95 OR mem_usage_pct > 95 THEN
        NEW.status := 'critical';
    ELSIF COALESCE(NEW.cpu_usage_percent, 0) > 80 OR disk_usage_pct > 85 OR mem_usage_pct > 85 THEN
        NEW.status := 'warning';
    ELSE
        NEW.status := 'healthy';
    END IF;

    RETURN NEW;
END;

DECLARE
  v_ad_id   uuid;
  v_ad_row  public.ads%ROWTYPE;
BEGIN
  INSERT INTO public.ads (
    team_id, name, status, creative_type, headline, ad_copy, call_to_action,
    content, media_urls, scheduled_at, ad_group_id, creative_url, platform_ad_id,
    preview_url, budget, updated_at
  )
  VALUES (
    p_team_id, p_name, p_status, p_creative_type, p_headline, p_ad_copy, p_call_to_action,
    p_content, p_media_urls, p_scheduled_at, p_ad_group_id, p_creative_url, p_platform_ad_id,
    p_preview_url, p_budget, now()
  )
  RETURNING * INTO v_ad_row;

  v_ad_id := v_ad_row.id;

  INSERT INTO public.social_posts (
    id, team_id, platform_id, post_type, post_channel,
    name, content, media_urls, status, scheduled_at, ad_group_id
  )
  VALUES (
    v_ad_id, p_team_id, p_platform_id, p_creative_type, 'ad',
    p_name, p_content, p_media_urls, p_status, p_scheduled_at, p_ad_group_id
  );

  RETURN row_to_json(v_ad_row);
END;

DECLARE
  v_count int := 0;
  v_member_rec record;
  v_prefs record;
BEGIN
  FOR v_member_rec IN
    SELECT DISTINCT wm.user_id, wm.team_id
    FROM workspace_members wm
    WHERE wm.status = 'active'
    UNION
    SELECT w.owner_id, w.id FROM workspaces w
  LOOP
    SELECT * INTO v_prefs FROM get_notification_preferences(v_member_rec.user_id) LIMIT 1;
    IF v_prefs.weekly_digest THEN
      INSERT INTO public.workspace_notifications (
        workspace_id, user_id, type, title, body, link
      ) VALUES (
        v_member_rec.team_id,
        v_member_rec.user_id,
        'weekly_digest',
        'Weekly Performance Digest',
        'Your weekly analytics summary is ready. View your reports and growth metrics.',
        '/reports'
      );
      v_count := v_count + 1;
    END IF;
  END LOOP;

  RETURN v_count;
END;

DECLARE
  report text := '';
  v_user_id uuid;
  v_team_count integer;
  v_ad_account_count integer;
  v_insight_count integer;
  v_orphan_insights integer;
  v_visible_insights integer;
BEGIN
  -- 1. Check current user (this will be NULL if called by Anon, but we want to simulate or check generally)
  -- Since we call this via Anon API, 'auth.uid()' will be null. 
  -- We need to pass a user_id or just report global stats to see if data exists at all.

  -- Let's just report GLOBAL stats first to confirm data integrity.
  report := report || '--- GLOBAL DATA STATS (Bypassing RLS) ---' || E'\n';

  SELECT count(*) INTO v_team_count FROM public.workspaces;
  report := report || 'Workspaces: ' || v_team_count || E'\n';

  SELECT count(*) INTO v_ad_account_count FROM public.ad_accounts;
  report := report || 'Ad Accounts: ' || v_ad_account_count || E'\n';

  SELECT count(*) INTO v_insight_count FROM public.ad_insights;
  report := report || 'Ad Insights (Total): ' || v_insight_count || E'\n';

  -- 2. Check for Orphaned Insights (ad_account_id not in ad_accounts)
  SELECT count(*) INTO v_orphan_insights 
  FROM public.ad_insights ai
  LEFT JOIN public.ad_accounts aa ON ai.ad_account_id = aa.id
  WHERE aa.id IS NULL;

  report := report || 'Orphaned Insights (Invalid ad_account_id): ' || v_orphan_insights || E'\n';

  -- 3. Check for Accounts without Team
  DECLARE
    v_orphan_accounts integer;
  BEGIN
    SELECT count(*) INTO v_orphan_accounts
    FROM public.ad_accounts
    WHERE team_id IS NULL;
    report := report || 'Orphaned Accounts (No team_id): ' || v_orphan_accounts || E'\n';
  END;

  -- 4. Sample Data check
  IF v_insight_count > 0 THEN
      DECLARE
        r record;
      BEGIN
        report := report || E'\n--- LATEST 3 INSIGHTS ---' || E'\n';
        FOR r IN SELECT date, ad_account_id, impressions, spend FROM public.ad_insights ORDER BY date DESC LIMIT 3 LOOP
           report := report || 'Date: ' || r.date || ', AccID: ' || r.ad_account_id || ', Impr: ' || r.impressions || E'\n';

           -- Check if this Acc exists
           DECLARE
             v_acc_name text;
             v_team_id uuid;
           BEGIN
             SELECT account_name, team_id INTO v_acc_name, v_team_id FROM public.ad_accounts WHERE id = r.ad_account_id;
             IF FOUND THEN
                report := report || '  -> Linked Account: ' || v_acc_name || ' (Team: ' || v_team_id || ')' || E'\n';
             ELSE
                report := report || '  -> Linked Account: NOT FOUND' || E'\n';
             END IF;
           END;
        END LOOP;
      END;
  END IF;

  RETURN report;
END;

DECLARE
    v_severity   VARCHAR(20);
    v_desc       TEXT;
    v_metadata   JSONB;
    v_recent_count INT;
BEGIN
    -- เฉพาะ earn / bonus
    IF NEW.transaction_type NOT IN ('earn', 'bonus') THEN
        RETURN NEW;
    END IF;

    v_metadata := jsonb_build_object(
        'points_transaction_id', NEW.id,
        'points_amount', NEW.points_amount,
        'balance_after', NEW.balance_after
    );

    -- กฎ 1: แต้มขึ้นจู่ๆ เยอะเกิน
    IF COALESCE(NEW.points_amount, 0) >= 1000 THEN
        v_severity := 'critical';
        v_desc := 'แต้มขึ้นจู่ๆ ' || COALESCE(NEW.points_amount, 0) || ' คะแนนในครั้งเดียว — สูงผิดปกติ';
        INSERT INTO public.suspicious_activities (user_id, activity_type, severity, description, metadata)
        VALUES (NEW.user_id, 'large_single_earn', v_severity, v_desc, v_metadata);
        RETURN NEW;
    ELSIF COALESCE(NEW.points_amount, 0) >= 500 THEN
        v_severity := 'high';
        v_desc := 'แต้มขึ้นจู่ๆ ' || COALESCE(NEW.points_amount, 0) || ' คะแนน — น่าสงสัย';
        INSERT INTO public.suspicious_activities (user_id, activity_type, severity, description, metadata)
        VALUES (NEW.user_id, 'large_single_earn', v_severity, v_desc, v_metadata);
        RETURN NEW;
    END IF;

    -- กฎ 2: แต้มขึ้นไวเกิน (หลายครั้งใน 1 ชม.)
    SELECT COUNT(*)::int INTO v_recent_count
    FROM public.points_transactions
    WHERE user_id = NEW.user_id
      AND transaction_type IN ('earn', 'bonus')
      AND created_at >= now() - INTERVAL '1 hour'
      AND id != NEW.id;

    IF v_recent_count >= 5 THEN
        v_severity := 'high';
        v_desc := 'ได้รับคะแนน ' || (v_recent_count + 1) || ' ครั้งใน 1 ชั่วโมง — เร็วผิดปกติ';
        v_metadata := v_metadata || jsonb_build_object('earn_count_1h', v_recent_count + 1);
        INSERT INTO public.suspicious_activities (user_id, activity_type, severity, description, metadata)
        VALUES (NEW.user_id, 'rapid_points_spike', v_severity, v_desc, v_metadata);
        RETURN NEW;
    ELSIF v_recent_count >= 3 THEN
        v_severity := 'medium';
        v_desc := 'ได้รับคะแนน ' || (v_recent_count + 1) || ' ครั้งใน 1 ชั่วโมง — น่าสงสัย';
        v_metadata := v_metadata || jsonb_build_object('earn_count_1h', v_recent_count + 1);
        INSERT INTO public.suspicious_activities (user_id, activity_type, severity, description, metadata)
        VALUES (NEW.user_id, 'rapid_points_spike', v_severity, v_desc, v_metadata);
        RETURN NEW;
    END IF;

    RETURN NEW;
END;

DECLARE
  v_deleted INTEGER;
BEGIN
  DELETE FROM public.ingestion_staging WHERE batch_id = p_batch_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;

DECLARE
    v_user_id uuid;
    v_profile_id uuid;
    v_bronze_id uuid;
    v_lp_id uuid;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'not_authenticated';
    END IF;

    SELECT id INTO v_profile_id
    FROM public.profile_customers
    WHERE user_id = v_user_id
    LIMIT 1;

    IF v_profile_id IS NULL THEN
        RETURN;
    END IF;

    SELECT id INTO v_lp_id
    FROM public.loyalty_points
    WHERE profile_customer_id = v_profile_id
    LIMIT 1;

    IF v_lp_id IS NOT NULL THEN
        -- Sync loyalty_point_id if missing (fixes existing customers)
        UPDATE public.profile_customers
        SET loyalty_point_id = v_lp_id, updated_at = now()
        WHERE id = v_profile_id AND (loyalty_point_id IS NULL OR loyalty_point_id != v_lp_id);
        RETURN;
    END IF;

    SELECT id INTO v_bronze_id
    FROM public.loyalty_tiers
    WHERE name = 'Bronze' AND is_active = true
    LIMIT 1;

    IF v_bronze_id IS NOT NULL THEN
        INSERT INTO public.loyalty_points (
            profile_customer_id, loyalty_tier_id, point_balance, lifetime_points
        ) VALUES (v_profile_id, v_bronze_id, 0, 0)
        RETURNING id INTO v_lp_id;

        UPDATE public.profile_customers
        SET loyalty_point_id = v_lp_id, updated_at = now()
        WHERE id = v_profile_id;
    END IF;
END;

DECLARE
    r              RECORD;
    v_tier         RECORD;
    v_qualified_id  UUID;
    v_downgraded   INT := 0;
    v_cutoff       TIMESTAMPTZ;
    v_override_cutoff TIMESTAMPTZ;
BEGIN
    IF auth.uid() IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.employees WHERE user_id = auth.uid()) THEN
        RAISE EXCEPTION 'employees_only';
    END IF;

    FOR v_tier IN
        SELECT id, name, COALESCE(retention_period_days, 90) AS days
        FROM public.loyalty_tiers
        WHERE is_active = true AND retention_period_days IS NOT NULL
    LOOP
        v_cutoff := now() - (v_tier.days || ' days')::interval;
        v_override_cutoff := now() - (v_tier.days || ' days')::interval;

        FOR r IN
            SELECT lp.id, lp.profile_customer_id, lp.loyalty_tier_id, lp.lifetime_points, lp.manual_override_at
            FROM public.loyalty_points lp
            WHERE lp.loyalty_tier_id = v_tier.id
              AND COALESCE(lp.last_activity_at, lp.updated_at, lp.created_at) < v_cutoff
              -- Skip if Support manually overrode within retention period
              AND (lp.manual_override_at IS NULL OR lp.manual_override_at < v_override_cutoff)
        LOOP
            SELECT id INTO v_qualified_id
            FROM public.loyalty_tiers
            WHERE is_active = true
              AND COALESCE(min_points, 0) <= COALESCE(r.lifetime_points, 0)
            ORDER BY priority_level DESC
            LIMIT 1;

            IF v_qualified_id IS NOT NULL AND v_qualified_id IS DISTINCT FROM r.loyalty_tier_id THEN
                UPDATE public.loyalty_points
                SET loyalty_tier_id = v_qualified_id, updated_at = now()
                WHERE id = r.id;
                v_downgraded := v_downgraded + 1;
            END IF;
        END LOOP;
    END LOOP;

    RETURN jsonb_build_object('downgraded_count', v_downgraded);
END;

DECLARE
    v_old_tier_name TEXT;
    v_new_tier_name TEXT;
    v_recent_manual_count INT;
BEGIN
    -- Only act if the tier ID actually changed
    IF OLD.loyalty_tier_id IS DISTINCT FROM NEW.loyalty_tier_id THEN

        -- Resolve Old Tier Name safely
        IF OLD.loyalty_tier_id IS NOT NULL THEN
            SELECT name INTO v_old_tier_name FROM public.loyalty_tiers WHERE id = OLD.loyalty_tier_id;
        END IF;

        -- Resolve New Tier Name
        IF NEW.loyalty_tier_id IS NOT NULL THEN
            SELECT name INTO v_new_tier_name FROM public.loyalty_tiers WHERE id = NEW.loyalty_tier_id;
        END IF;

        -- Prevent duplicate auto-logging if a manual override JUST happened in the same second/transaction
        -- We check if there's a 'manual' entry in the last 2 seconds for this same tier change
        SELECT COUNT(*)
        INTO v_recent_manual_count
        FROM public.loyalty_tier_history
        WHERE profile_customer_id = NEW.profile_customer_id
          AND change_type = 'manual'
          AND new_tier = v_new_tier_name
          AND changed_at >= NOW() - INTERVAL '2 seconds';

        IF v_recent_manual_count = 0 THEN
            -- Only insert auto log if we didn't just do a manual override
            INSERT INTO public.loyalty_tier_history (
                profile_customer_id,
                old_tier,
                new_tier,
                change_type,
                changed_at
            ) VALUES (
                NEW.profile_customer_id,
                COALESCE(v_old_tier_name, 'None'),
                COALESCE(v_new_tier_name, 'None'),
                'auto',
                NOW()
            );
        END IF;

    END IF;
    RETURN NEW;
END;

DECLARE
  v_workspace_id uuid;
  v_budget_name text;
  v_spend_pct numeric;
  v_member_rec record;
  v_prefs record;
BEGIN
  -- Only fire when spent_amount changes and crosses threshold
  IF NEW.spent_amount IS NULL OR NEW.amount IS NULL OR NEW.amount <= 0 THEN
    RETURN NEW;
  END IF;

  v_spend_pct := (NEW.spent_amount / NEW.amount) * 100;
  IF v_spend_pct < NEW.alert_threshold_percent THEN
    RETURN NEW;
  END IF;

  -- Avoid duplicate alerts: skip if we already notified this user for this budget recently (24h)
  IF EXISTS (
    SELECT 1 FROM workspace_notifications
    WHERE related_id = NEW.id
      AND type = 'budget_alert'
      AND created_at > now() - interval '24 hours'
  ) THEN
    RETURN NEW;
  END IF;

  v_workspace_id := NEW.team_id;
  v_budget_name := NEW.name;

  -- Notify workspace owner + members who have push_notifications enabled
  FOR v_member_rec IN
    SELECT owner_id AS uid FROM workspaces WHERE id = v_workspace_id
    UNION
    SELECT user_id AS uid FROM workspace_members
    WHERE team_id = v_workspace_id AND status = 'active'
  LOOP
    SELECT * INTO v_prefs FROM get_notification_preferences(v_member_rec.uid) LIMIT 1;
    IF v_prefs.push_notifications THEN
      INSERT INTO public.workspace_notifications (
        workspace_id, user_id, type, title, body, link, related_id
      ) VALUES (
        v_workspace_id,
        v_member_rec.uid,
        'budget_alert',
        'Budget alert: ' || v_budget_name,
        'Spend has reached ' || round(v_spend_pct, 1) || '% of budget (threshold: ' || NEW.alert_threshold_percent || '%).',
        '/settings',
        NEW.id
      );
    END IF;
  END LOOP;

  RETURN NEW;
END;

