DECLARE
  v_impressions bigint := 0;
  v_clicks bigint := 0;
  v_leads bigint := 0;
  v_adds_to_cart bigint := 0;
  v_conversions bigint := 0;
  v_leads_estimated boolean := false;
  v_adds_to_cart_estimated boolean := false;
  v_conversions_estimated boolean := false;
  v_raw record;
BEGIN
  SELECT
    COALESCE(SUM(ai.impressions), 0)::bigint,
    COALESCE(SUM(ai.clicks), 0)::bigint,
    COALESCE(SUM(ai.leads), 0)::bigint,
    COALESCE(SUM(ai.adds_to_cart), 0)::bigint,
    COALESCE(SUM(ai.conversions), 0)::bigint
  INTO v_impressions, v_clicks, v_leads, v_adds_to_cart, v_conversions
  FROM ad_insights ai
  INNER JOIN ad_accounts aa ON aa.id = ai.ad_account_id AND aa.is_active = true
  WHERE (p_date_from IS NULL OR ai.date >= p_date_from)
    AND (p_platform_id IS NULL OR aa.platform_id = p_platform_id);

  -- Fallback: many ad platforms don't report leads/adds_to_cart; use estimates
  IF v_leads = 0 AND v_clicks > 0 THEN
    v_leads := ROUND(v_clicks * 0.05)::bigint;
    v_leads_estimated := true;
  END IF;

  IF v_adds_to_cart = 0 AND (v_leads > 0 OR v_conversions > 0) THEN
    v_adds_to_cart := GREATEST(
      ROUND(v_leads * 0.25)::bigint,
      ROUND(v_conversions * 2.5)::bigint
    );
    v_adds_to_cart_estimated := true;
  END IF;

  IF v_conversions = 0 AND v_adds_to_cart > 0 THEN
    v_conversions := ROUND(v_adds_to_cart * 0.35)::bigint;
    v_conversions_estimated := true;
  END IF;

  RETURN jsonb_build_object(
    'totals', jsonb_build_object(
      'impressions', v_impressions,
      'clicks', v_clicks,
      'leads', v_leads,
      'adds_to_cart', v_adds_to_cart,
      'conversions', v_conversions
    ),
    'used_fallback', jsonb_build_object(
      'leads', v_leads_estimated,
      'adds_to_cart', v_adds_to_cart_estimated,
      'conversions', v_conversions_estimated
    )
  );
END;

DECLARE
  v_month_key text;
  v_date date;
  v_i int;
  v_imp bigint;
  v_clicks bigint;
  v_leads bigint;
  v_atc bigint;
  v_conv bigint;
  v_leads_est boolean;
  v_atc_est boolean;
  v_conv_est boolean;
BEGIN
  -- REVERSE form must be high..low; (p_months_back - 1)..0 yields oldest→newest.
  FOR v_i IN REVERSE (p_months_back - 1)..0 LOOP
    v_date := (CURRENT_DATE - (v_i || ' months')::interval)::date;
    v_month_key := to_char(v_date, 'YYYY-MM');

    SELECT
      COALESCE(SUM(ai.impressions), 0)::bigint,
      COALESCE(SUM(ai.clicks), 0)::bigint,
      COALESCE(SUM(ai.leads), 0)::bigint,
      COALESCE(SUM(ai.adds_to_cart), 0)::bigint,
      COALESCE(SUM(ai.conversions), 0)::bigint
    INTO v_imp, v_clicks, v_leads, v_atc, v_conv
    FROM ad_insights ai
    INNER JOIN ad_accounts aa ON aa.id = ai.ad_account_id AND aa.is_active = true
    WHERE ai.date >= date_trunc('month', v_date)::date
      AND ai.date < date_trunc('month', v_date)::date + interval '1 month'
      AND (p_platform_id IS NULL OR aa.platform_id = p_platform_id);

    v_leads_est := false;
    v_atc_est := false;
    v_conv_est := false;

    IF v_leads = 0 AND v_clicks > 0 THEN
      v_leads := ROUND(v_clicks * 0.05)::bigint;
      v_leads_est := true;
    END IF;

    IF v_atc = 0 AND (v_leads > 0 OR v_conv > 0) THEN
      v_atc := GREATEST(
        ROUND(v_leads * 0.25)::bigint,
        ROUND(v_conv * 2.5)::bigint
      );
      v_atc_est := true;
    END IF;

    IF v_conv = 0 AND v_atc > 0 THEN
      v_conv := ROUND(v_atc * 0.35)::bigint;
      v_conv_est := true;
    END IF;

    month := v_month_key;
    month_label := to_char(v_date, 'Mon yy');
    awareness := v_imp;
    consideration := v_clicks;
    acquisition := v_leads;
    intent := v_atc;
    conversion := v_conv;
    acquisition_is_estimated := v_leads_est;
    intent_is_estimated := v_atc_est;
    conversion_is_estimated := v_conv_est;
    RETURN NEXT;
  END LOOP;
END;

DECLARE
    v_user_id uuid;
    v_result jsonb;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('tier', null, 'point_balance', 0);
    END IF;

    SELECT jsonb_build_object(
        'tier', to_jsonb(lt.*),
        'point_balance', COALESCE(lp.point_balance, 0)
    ) INTO v_result
    FROM public.profile_customers pc
    JOIN public.loyalty_points lp ON lp.profile_customer_id = pc.id
    LEFT JOIN public.loyalty_tiers lt ON lt.id = lp.loyalty_tier_id
    WHERE pc.user_id = v_user_id
    LIMIT 1;

    IF v_result IS NULL THEN
        -- No loyalty_points: return Bronze as default
        SELECT jsonb_build_object(
            'tier', to_jsonb(lt.*),
            'point_balance', 0
        ) INTO v_result
        FROM public.loyalty_tiers lt
        WHERE lt.name = 'Bronze' AND lt.is_active = true
        LIMIT 1;
    END IF;

    RETURN COALESCE(v_result, jsonb_build_object('tier', null, 'point_balance', 0));
END;

DECLARE
    v_new_tier_id UUID;
    v_user_id UUID;
    v_point_diff INT;
BEGIN
    -- 1. จัดการเรื่อง Total Points (บวกเพิ่มให้ตามส่วนต่างที่เพิ่มขึ้น)
    v_point_diff := NEW.point_balance - OLD.point_balance;
    IF v_point_diff > 0 THEN
        NEW.total_points_earned := COALESCE(NEW.total_points_earned, 0) + v_point_diff;
    END IF;

    -- 2. Support manual override: NEVER overwrite tier. Support's choice takes precedence.
    IF NEW._override_changer_id IS NOT NULL OR OLD.manual_override_at IS NOT NULL THEN
        RETURN NEW;
    END IF;

    -- 3. ค้นหา Tier ที่เหมาะสมตามแต้มสะสมทั้งหมด (total_points_earned)
    SELECT id
    INTO v_new_tier_id
    FROM public.loyalty_tiers
    WHERE min_points <= NEW.total_points_earned
      AND is_active = true
    ORDER BY priority_level DESC
    LIMIT 1;

    -- 4. ถ้าผลลัพธ์คือต้องเปลี่ยน Tier
    IF v_new_tier_id IS NOT NULL AND (OLD.loyalty_tier_id IS NULL OR v_new_tier_id != OLD.loyalty_tier_id) THEN
        NEW.loyalty_tier_id := v_new_tier_id;

        SELECT user_id INTO v_user_id
        FROM public.profile_customers
        WHERE id = NEW.profile_customer_id;

        IF v_user_id IS NOT NULL THEN
            INSERT INTO public.tier_history (
                user_id,
                previous_tier_id,
                new_tier_id,
                change_reason,
                is_manual_override
            ) VALUES (
                v_user_id,
                OLD.loyalty_tier_id,
                v_new_tier_id,
                'System: Tier adjustment based on total points earned (' || NEW.total_points_earned || ' pts)',
                false
            );
        END IF;
    END IF;

    RETURN NEW;
END;

