DECLARE
    v_caller_id          UUID;
    v_profile_customer_id UUID;
    v_lp_id              UUID;
    v_old_tier_id        UUID;
    v_old_tier_name      TEXT;
    v_new_tier_name      TEXT;
BEGIN
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'not_authenticated';
    END IF;

    IF NOT public.is_employee(v_caller_id) THEN
        RAISE EXCEPTION 'permission_denied: only employees can call this function';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.loyalty_tiers WHERE id = new_tier_id) THEN
        RAISE EXCEPTION 'tier_not_found: %', new_tier_id;
    END IF;

    -- Resolve new_tier name from loyalty_tiers
    SELECT name INTO v_new_tier_name
    FROM public.loyalty_tiers
    WHERE id = new_tier_id;

    -- Step 1: Lock profile_customers ONLY (no join — avoids FOR UPDATE on outer join)
    SELECT pc.id INTO v_profile_customer_id
    FROM public.profile_customers pc
    WHERE pc.user_id = target_user_id
    FOR UPDATE;

    IF v_profile_customer_id IS NULL THEN
        RAISE EXCEPTION 'customer_not_found: no profile for user %', target_user_id;
    END IF;

    -- Step 2: Read loyalty_points (no lock — simple SELECT, may return NULL for new users)
    SELECT lp.id, lp.loyalty_tier_id INTO v_lp_id, v_old_tier_id
    FROM public.loyalty_points lp
    WHERE lp.profile_customer_id = v_profile_customer_id;

    -- Reject if tier unchanged (prevents Gold→Gold history entries)
    IF v_old_tier_id IS NOT DISTINCT FROM new_tier_id THEN
        RAISE EXCEPTION 'tier_unchanged: select a different tier';
    END IF;

    IF v_lp_id IS NULL THEN
        -- New user: create loyalty_points row
        INSERT INTO public.loyalty_points (
            profile_customer_id,
            point_balance,
            lifetime_points,
            loyalty_tier_id,
            _override_changer_id
        ) VALUES (
            v_profile_customer_id,
            0,
            0,
            new_tier_id,
            v_caller_id
        ) RETURNING id INTO v_lp_id;

        UPDATE public.loyalty_points
        SET _override_changer_id = NULL
        WHERE id = v_lp_id;

        v_old_tier_name := 'None';
    ELSE
        IF v_old_tier_id IS NOT NULL THEN
            SELECT name INTO v_old_tier_name
            FROM public.loyalty_tiers
            WHERE id = v_old_tier_id;
        END IF;
        v_old_tier_name := COALESCE(v_old_tier_name, 'None');

        -- Update tier (marker prevents trigger from logging)
        UPDATE public.loyalty_points
        SET loyalty_tier_id = new_tier_id,
            updated_at      = now(),
            _override_changer_id = v_caller_id
        WHERE id = v_lp_id;

        UPDATE public.loyalty_points
        SET _override_changer_id = NULL
        WHERE id = v_lp_id;

        -- Re-fetch new_tier name from actual row
        SELECT lt.name INTO v_new_tier_name
        FROM public.loyalty_points lp
        JOIN public.loyalty_tiers lt ON lt.id = lp.loyalty_tier_id
        WHERE lp.id = v_lp_id;
    END IF;

    v_new_tier_name := COALESCE(v_new_tier_name, (
        SELECT name FROM public.loyalty_tiers WHERE id = new_tier_id
    ), 'Unknown');

    INSERT INTO public.loyalty_tier_history (
        profile_customer_id,
        old_tier,
        new_tier,
        change_type,
        change_reason,
        changer_id
    ) VALUES (
        v_profile_customer_id,
        v_old_tier_name,
        v_new_tier_name,
        'manual',
        COALESCE(override_reason, 'Manual override by support'),
        v_caller_id
    );

    BEGIN
        INSERT INTO public.tier_history (
            user_id,
            previous_tier_id,
            new_tier_id,
            change_reason,
            changed_by,
            is_manual_override
        ) VALUES (
            target_user_id,
            v_old_tier_id,
            new_tier_id,
            COALESCE(override_reason, 'Manual override by support'),
            v_caller_id,
            true
        );
    EXCEPTION WHEN others THEN
        RAISE WARNING 'tier_history insert failed (non-fatal): %', SQLERRM;
    END;

    RETURN jsonb_build_object(
        'success',  true,
        'old_tier', v_old_tier_name,
        'new_tier', v_new_tier_name
    );
END;

DECLARE
  v_rec record;
  v_email text;
  v_user_id uuid;
  v_prefs record;
  v_recipients jsonb;
  v_next_run timestamptz;
BEGIN
  FOR v_rec IN
    SELECT sr.id, sr.team_id, sr.name, sr.frequency, sr.recipients, sr.next_run_at
    FROM scheduled_reports sr
    WHERE sr.is_active
      AND sr.next_run_at IS NOT NULL
      AND sr.next_run_at <= now()
  LOOP
    v_recipients := v_rec.recipients;
    IF jsonb_typeof(v_recipients) = 'array' THEN
      FOR v_email IN SELECT jsonb_array_elements_text(v_recipients)
      LOOP
        IF v_email IS NOT NULL AND trim(v_email) != '' THEN
          -- Resolve email to user_id (auth.users)
          SELECT id INTO v_user_id FROM auth.users WHERE email = v_email LIMIT 1;
          IF v_user_id IS NOT NULL THEN
            SELECT * INTO v_prefs FROM get_notification_preferences(v_user_id) LIMIT 1;
            IF v_prefs.email_reports THEN
              report_id := v_rec.id;
              recipient_user_id := v_user_id;
              recipient_email := v_email;
              report_name := v_rec.name;
              RETURN NEXT;
            END IF;
          END IF;
        END IF;
      END LOOP;
    END IF;

    -- Update next_run_at (compute next run from frequency)
    v_next_run := CASE v_rec.frequency
      WHEN 'daily' THEN now() + interval '1 day'
      WHEN 'weekly' THEN now() + interval '1 week'
      WHEN 'monthly' THEN now() + interval '1 month'
      ELSE now() + interval '1 week'
    END;

    UPDATE scheduled_reports
    SET last_run_at = now(), next_run_at = v_next_run, updated_at = now()
    WHERE id = v_rec.id;
  END LOOP;
END;

DECLARE
    v_user_id            UUID;
    v_user_email         TEXT;
    v_customer_name      TEXT;
    v_loyalty_points_id  UUID;
    v_point_balance      INTEGER;
    v_points_cost        INTEGER;
    v_stock_quantity     INTEGER;
    v_reward_name        TEXT;
    v_new_balance        INTEGER;
    v_tx_id              UUID;
    v_coupon_code        TEXT;
    v_attempt            INTEGER := 0;
    v_discount_id        UUID;
    v_pc_id              UUID;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'not_authenticated';
    END IF;

    -- Ensure customer exists (FK for reward_redemptions + points_transactions)
    INSERT INTO public.customer (id, email, full_name, plan_type)
    SELECT
        au.id,
        COALESCE(au.email, 'unknown@buzzly.local'),
        COALESCE(
            NULLIF(TRIM(COALESCE(pc.first_name, '') || ' ' || COALESCE(pc.last_name, '')), ''),
            au.email,
            'Customer'
        ),
        'free'
    FROM auth.users au
    LEFT JOIN public.profile_customers pc ON pc.user_id = au.id
    WHERE au.id = v_user_id
    ON CONFLICT (id) DO NOTHING;

    SELECT au.email, TRIM(COALESCE(pc.first_name, '') || ' ' || COALESCE(pc.last_name, ''))
    INTO v_user_email, v_customer_name
    FROM auth.users au
    LEFT JOIN public.profile_customers pc ON pc.user_id = au.id
    WHERE au.id = v_user_id;

    -- Fetch or auto-create loyalty_points (like award_loyalty_points)
    SELECT lp.id, lp.point_balance
    INTO v_loyalty_points_id, v_point_balance
    FROM profile_customers pc
    JOIN loyalty_points lp ON lp.profile_customer_id = pc.id
    WHERE pc.user_id = v_user_id
    FOR UPDATE OF lp;

    IF v_loyalty_points_id IS NULL THEN
        SELECT id INTO v_pc_id FROM public.profile_customers WHERE user_id = v_user_id;
        IF v_pc_id IS NULL THEN
            RAISE EXCEPTION 'loyalty_points_not_found';
        END IF;
        INSERT INTO public.loyalty_points (
            profile_customer_id,
            point_balance,
            lifetime_points,
            last_activity_at
        )
        VALUES (
            v_pc_id,
            0,
            0,
            now()
        )
        ON CONFLICT (profile_customer_id) DO NOTHING;

        SELECT id INTO v_loyalty_points_id
        FROM public.loyalty_points
        WHERE profile_customer_id = v_pc_id;

        v_point_balance := 0;
    END IF;

    IF v_loyalty_points_id IS NULL THEN
        RAISE EXCEPTION 'loyalty_points_not_found';
    END IF;

    SELECT ri.points_cost, ri.stock_quantity, ri.name
    INTO v_points_cost, v_stock_quantity, v_reward_name
    FROM reward_items ri
    WHERE ri.id = p_reward_item_id AND ri.is_active = true
    FOR UPDATE;

    IF v_points_cost IS NULL THEN
        RAISE EXCEPTION 'reward_not_found';
    END IF;
    IF v_stock_quantity IS NOT NULL AND v_stock_quantity <= 0 THEN
        RAISE EXCEPTION 'out_of_stock';
    END IF;
    IF v_point_balance < v_points_cost THEN
        RAISE EXCEPTION 'insufficient_points';
    END IF;

    v_new_balance := v_point_balance - v_points_cost;

    UPDATE loyalty_points
    SET point_balance = v_new_balance,
        last_activity_at = now(),
        updated_at = now()
    WHERE id = v_loyalty_points_id;

    INSERT INTO points_transactions (
        user_id, loyalty_points_id, transaction_type, points_amount, balance_after, description
    ) VALUES (
        v_user_id, v_loyalty_points_id, 'spend', v_points_cost, v_new_balance,
        'Redeemed: ' || v_reward_name
    )
    RETURNING id INTO v_tx_id;

    INSERT INTO reward_redemptions (user_id, reward_id, points_transaction_id, status)
    VALUES (v_user_id, p_reward_item_id, v_tx_id, 'pending');

    IF v_stock_quantity IS NOT NULL THEN
        UPDATE reward_items SET stock_quantity = stock_quantity - 1
        WHERE id = p_reward_item_id;
    END IF;

    LOOP
        v_coupon_code := 'BUZZ-'
            || upper(substring(md5(random()::text || clock_timestamp()::text) from 1 for 4))
            || '-' || upper(substring(md5(random()::text || clock_timestamp()::text) from 5 for 4));
        IF NOT EXISTS (SELECT 1 FROM user_redeemed_coupons WHERE coupon_code = v_coupon_code)
           AND NOT EXISTS (SELECT 1 FROM discounts WHERE code = v_coupon_code)
        THEN EXIT; END IF;
        v_attempt := v_attempt + 1;
        IF v_attempt >= 10 THEN
            RAISE EXCEPTION 'Failed to generate unique coupon code after 10 attempts';
        END IF;
    END LOOP;

    -- Insert into discounts (NO team_id — column was dropped in 20260306000001)
    BEGIN
        INSERT INTO public.discounts (
            code,
            name,
            discount_type,
            discount_value,
            usage_limit,
            is_active,
            published_at,
            description
        ) VALUES (
            v_coupon_code,
            'Loyalty Reward — ' || v_reward_name,
            'percent',
            20,
            1,
            true,
            now(),
            'Auto-generated loyalty reward for: ' || COALESCE(v_user_email, v_user_id::text)
        )
        RETURNING id INTO v_discount_id;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'Could not insert into discounts: %', SQLERRM;
    END;

    INSERT INTO user_redeemed_coupons (user_id, reward_item_id, coupon_code, user_email, customer_name)
    VALUES (v_user_id, p_reward_item_id, v_coupon_code, v_user_email, NULLIF(v_customer_name, ''));

    INSERT INTO public.customer_notifications (customer_id, title, message, type, related_id)
    VALUES (
        v_user_id, '🎉 Reward Redeemed Successfully!',
        'Your discount code is: ' || v_coupon_code || '. Use it at checkout for 20% off — valid for 1 use.',
        'reward', v_discount_id
    );

    RETURN jsonb_build_object('success', true, 'new_balance', v_new_balance, 'coupon_code', v_coupon_code);
END;

DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;

BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'not_authenticated';
    END IF;

    -- Support, Owner, Dev (same roles that can access /support/tier-management)
    IF NOT (
        public.has_employee_role(auth.uid(), 'support')
        OR public.has_employee_role(auth.uid(), 'owner')
        OR public.has_employee_role(auth.uid(), 'dev')
        OR public.is_employee(auth.uid())
    ) THEN
        RAISE EXCEPTION 'permission_denied: employees only';
    END IF;

    p_query := trim(p_query);
    IF length(p_query) < 1 THEN
        RETURN;
    END IF;

    p_query := replace(replace(replace(p_query, '\', '\\'), '%', '\%'), '_', '\_');
    p_query := '%' || p_query || '%';

    RETURN QUERY
    SELECT
        pc.user_id::uuid AS id,
        (NULLIF(trim(coalesce(pc.first_name, '') || ' ' || coalesce(pc.last_name, '')), ''))::text AS full_name,
        (COALESCE(c.email, au.email))::text AS email,
        pc.created_at::timestamptz AS created_at,
        (lt.name)::text AS loyalty_tier,
        (coalesce(lp.point_balance, 0))::integer AS loyalty_points_balance
    FROM public.profile_customers pc
    LEFT JOIN auth.users au ON au.id = pc.user_id
    LEFT JOIN public.customer c ON c.id = pc.user_id
    LEFT JOIN public.loyalty_points lp ON lp.profile_customer_id = pc.id
    LEFT JOIN public.loyalty_tiers lt ON lt.id = lp.loyalty_tier_id
    WHERE
        (pc.first_name IS NOT NULL AND pc.first_name ILIKE p_query)
        OR (pc.last_name IS NOT NULL AND pc.last_name ILIKE p_query)
        OR (trim(coalesce(pc.first_name, '') || ' ' || coalesce(pc.last_name, '')) ILIKE p_query)
        OR (trim(coalesce(pc.last_name, '') || ' ' || coalesce(pc.first_name, '')) ILIKE p_query)
        OR (COALESCE(c.email, au.email) IS NOT NULL AND (COALESCE(c.email, au.email))::text ILIKE p_query)
        OR (pc.user_id::text ILIKE p_query)
    ORDER BY pc.first_name, pc.last_name
    LIMIT 15;
END;

DECLARE
    v_caller_id    UUID := auth.uid();
    v_discount     RECORD;
    v_title        TEXT;
    v_message      TEXT;
BEGIN
    -- 1. Caller must be an employee (owner, dev, support)
    IF v_caller_id IS NULL OR NOT public.is_employee(v_caller_id) THEN
        RAISE EXCEPTION 'not_authorized';
    END IF;

    -- 2. Validate customer exists (profile_customers.user_id = auth.users.id)
    IF NOT EXISTS (SELECT 1 FROM public.profile_customers WHERE user_id = p_customer_id) THEN
        RAISE EXCEPTION 'customer_not_found';
    END IF;

    -- 3. Fetch discount
    SELECT id, code, discount_type, discount_value, published_at
    INTO v_discount
    FROM public.discounts
    WHERE id = p_discount_id;

    IF v_discount.id IS NULL THEN
        RAISE EXCEPTION 'discount_not_found';
    END IF;

    -- 4. Publish discount if not yet published (so customer can collect)
    IF v_discount.published_at IS NULL THEN
        UPDATE public.discounts
        SET published_at = now(), updated_at = now()
        WHERE id = p_discount_id;
    END IF;

    -- 5. Build notification content based on context
    IF p_context = 're_engage' THEN
        v_title := 'We miss you! Special offer inside';
        v_message := 'Welcome back! Use code «' || v_discount.code || '» for '
            || CASE WHEN v_discount.discount_type = 'percent'
                THEN v_discount.discount_value::TEXT || '% off'
                ELSE '฿' || v_discount.discount_value::TEXT || ' off'
            END || '. Valid for one use.';
    ELSE
        v_title := 'Exclusive Promo Just For You!';
        v_message := 'You''re so close to the next tier! Use code «' || v_discount.code || '» for '
            || CASE WHEN v_discount.discount_type = 'percent'
                THEN v_discount.discount_value::TEXT || '% off'
                ELSE '฿' || v_discount.discount_value::TEXT || ' off'
            END || '. Collect it now!';
    END IF;

    -- 6. Insert into customer_notifications (customer sees in bell)
    INSERT INTO public.customer_notifications (
        customer_id,
        title,
        message,
        type,
        related_id
    ) VALUES (
        p_customer_id,
        v_title,
        v_message,
        'discount',
        p_discount_id
    );

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Promo sent to customer notification center'
    );
END;

DECLARE
    v_role_name text;
    v_app_role app_role;
BEGIN
    -- Get the role name from role_employees
    SELECT LOWER(role_name) INTO v_role_name
    FROM public.role_employees
    WHERE id = NEW.role_employees_id;

    -- Map 'developer' or 'dev' to 'dev' app_role
    -- Map 'admin' to 'admin' app_role
    -- Map 'owner' to 'owner' app_role
    -- Others defaults to null (no user_role entry)
    -- Map 'dev', 'admin', 'owner', 'support' to their respective app_roles
    IF NEW.user_id IS NOT NULL AND v_role_name IN ('owner', 'admin', 'dev', 'support') THEN
        v_app_role := v_role_name::app_role;

        -- Upsert into user_roles
        INSERT INTO public.user_roles (user_id, role)
        VALUES (NEW.user_id, v_app_role)
        ON CONFLICT (user_id, role) DO NOTHING;

        -- STRICT MAPPING: When a user becomes an employee, remove their customer role
        -- to ensure they are redirected to the employee dashboard
        DELETE FROM public.user_roles 
        WHERE user_id = NEW.user_id 
        AND role = 'customer';
    END IF;

    RETURN NEW;
END;

DECLARE
    r              RECORD;
    v_correct_id   UUID;
    v_updated      INT := 0;
    v_backfilled   INT := 0;
    v_override_cutoff TIMESTAMPTZ := now() - interval '90 days';
BEGIN
    IF auth.uid() IS NOT NULL AND NOT public.is_employee(auth.uid()) THEN
        RAISE EXCEPTION 'permission_denied: employees only';
    END IF;

    FOR r IN
        SELECT lp.id, lp.profile_customer_id, lp.loyalty_tier_id, lp.lifetime_points, lp.manual_override_at
        FROM public.loyalty_points lp
        WHERE lp.manual_override_at IS NULL OR lp.manual_override_at < v_override_cutoff
    LOOP
        SELECT id INTO v_correct_id
        FROM public.loyalty_tiers
        WHERE is_active = true
          AND COALESCE(min_points, 0) <= COALESCE(r.lifetime_points, 0)
        ORDER BY priority_level DESC
        LIMIT 1;

        IF v_correct_id IS NOT NULL AND v_correct_id IS DISTINCT FROM r.loyalty_tier_id THEN
            UPDATE public.loyalty_points
            SET loyalty_tier_id = v_correct_id, updated_at = now()
            WHERE id = r.id;
            v_updated := v_updated + 1;
        END IF;
    END LOOP;

    INSERT INTO public.loyalty_tier_history (
        profile_customer_id, old_tier, new_tier, change_type, change_reason, changed_at
    )
    SELECT lp.profile_customer_id, 'Bronze', lt.name, 'auto',
           'System auto-evaluated tier (sync)', NOW()
    FROM public.loyalty_points lp
    JOIN public.loyalty_tiers lt ON lt.id = lp.loyalty_tier_id
    WHERE lt.name IN ('Silver', 'Gold', 'Platinum')
      AND (lp.manual_override_at IS NULL OR lp.manual_override_at < v_override_cutoff)
      AND NOT EXISTS (
          SELECT 1 FROM public.loyalty_tier_history lth
          WHERE lth.profile_customer_id = lp.profile_customer_id
            AND lth.new_tier IN ('Silver', 'Gold', 'Platinum')
      );

    GET DIAGNOSTICS v_backfilled = ROW_COUNT;

    RETURN jsonb_build_object('updated_count', v_updated, 'backfilled_count', v_backfilled);
END;

DECLARE
  v_url    TEXT;
  v_secret TEXT;
BEGIN
  IF NEW.status IS DISTINCT FROM 'pending' THEN
    RETURN NEW;
  END IF;

  v_url    := NULLIF(public.pipeline_setting('airflow_trigger_url'), '');
  v_secret := NULLIF(public.pipeline_setting('airflow_trigger_secret'), '');

  IF v_url IS NULL OR v_secret IS NULL THEN
    RAISE LOG 'import_jobs webhook not configured (set airflow_trigger_url / airflow_trigger_secret); job % left for the sensor DAG', NEW.id;
    RETURN NEW;
  END IF;

  PERFORM http_post(
    url     := v_url,
    headers := jsonb_build_object(
                 'Content-Type', 'application/json',
                 'x-buzzly-trigger-secret', v_secret
               ),
    body    := jsonb_build_object(
                 'type',   'INSERT',
                 'table',  'import_jobs',
                 'record', jsonb_build_object('id', NEW.id, 'status', NEW.status)
               ),
    timeout_milliseconds := 5000
  );

  RETURN NEW;
EXCEPTION WHEN others THEN
  RAISE WARNING 'Airflow webhook failed for import job % (%); leaving it for the sensor DAG.', NEW.id, SQLERRM;
  RETURN NEW;
END;

